import{_ as t,o,c as a,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const n="/assets/analytics-create-account.C4Hm-tgw.png",s="/assets/analytics-start-collecting-data.B8OvnfxP.png",l="/assets/analytics-create-custom-dimensions.2F1DzdVf.png",r="/assets/analytics-admin-data-streams.DUChL1Ip.png",c="/assets/analytics-select-specific-stream.B3i24oe0.png",d="/assets/analytics-measurement-id.Bw309tQk.png",p="/assets/analytics-elevator-admin-key.i26QN6JZ.png",u="/assets/analytics-using-tag-assistant.DJYsVyGq.mp4",g="/assets/analytics-report.B9ujNR5X.png",A=JSON.parse('{"title":"Google Analytics","description":"","frontmatter":{},"headers":[],"relativePath":"google-analytics.md","filePath":"google-analytics.md"}'),m={name:"google-analytics.md"};function h(y,e,f,v,b,w){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="google-analytics" tabindex="-1">Google Analytics <a class="header-anchor" href="#google-analytics" aria-label="Permalink to &quot;Google Analytics&quot;">​</a></h1><p>Admins can set up Google Analytics for greater visibility into what assets are viewed and downloaded.</p><h2 id="create-an-account" tabindex="-1">Create an Account <a class="header-anchor" href="#create-an-account" aria-label="Permalink to &quot;Create an Account&quot;">​</a></h2><p>If this is your first time using Google Analytics at your institution, you may need to create a Google Analytics account. If you already have an account, skip this step.</p><ol><li><p>Go to <a href="https://analytics.google.com" target="_blank" rel="noreferrer">analytics.google.com</a> and login.</p></li><li><p>In the <code>Admin</code> menu, choose <code>+ Create &gt; Account</code>.</p><p><img src="'+n+'" alt="Create account in Analytics"></p></li><li><p>Under <code>Account Details</code>, enter your organization name, e.g. &quot;UMN College of Liberal Arts&quot;.</p></li><li><p>Under <code>Account Data Sharing Settings</code>, choose if you wish to share any data, otherwise uncheck all the boxes.</p></li><li><p>Click <code>Next</code>.</p></li></ol><h2 id="create-a-property" tabindex="-1">Create a Property <a class="header-anchor" href="#create-a-property" aria-label="Permalink to &quot;Create a Property&quot;">​</a></h2><p>Within Google Analytics, each website you wish to track is called a &quot;Property&quot;.</p><ol><li><p>Under <code>Property Name</code>, enter your elevator instance name, e.g. &quot;dcl.elevator.umn.edu&quot;.</p></li><li><p>Set your time zone, and click <code>Next</code></p></li><li><p>Answer the questions under <code>Business Details</code>, and click <code>Next</code></p></li><li><p>Set you <code>business objectives</code>, e.g. &quot;understand usage&quot;</p></li><li><p>Review and accept the <code>Terms of Service</code> if you wish.</p></li><li><p>Under <code>Start Collecting Data</code>, choose <code>Web</code>, then:</p><ul><li>Enter your website url, e.g. <code>dcl.elevator.umn.edu</code></li><li>Put your instance name as the <code>Stream name</code>, e.g. <code>UMN Digital Content Library</code></li><li>Be sure <code>Enhanced Measurement</code> option is checked to gather page views and downloads.</li></ul><p><img src="'+s+'" alt="Start collecting data screen"></p></li><li><p>Finally, click <code>Create &amp; Continue</code> to generate your elevator instance.</p></li></ol><h2 id="set-up-custom-dimensions-in-analytics" tabindex="-1">Set up Custom Dimensions in Analytics <a class="header-anchor" href="#set-up-custom-dimensions-in-analytics" aria-label="Permalink to &quot;Set up Custom Dimensions in Analytics&quot;">​</a></h2><p>In addition to default analytics info like page views, you can get Elevator-specific data about assets, collections, and file downloads if you set <strong>Custom Dimensions</strong> in Google Analaytics.</p><ol><li><p>Go to <code>Admin &gt; Data Display &gt; Custom Definitions</code></p><p><img src="'+l+'" alt="Create custom dimensions"></p></li><li><p>Under <code>Custom Dimensions</code> tab, create the following custom dimensions:</p></li></ol><table tabindex="0"><thead><tr><th>Dimension Name</th><th>Scope</th><th>Event Parameter</th></tr></thead><tbody><tr><td>Instance ID</td><td>Event</td><td><code>instance_id</code></td></tr><tr><td>Instance Name</td><td>Event</td><td><code>instance_name</code></td></tr><tr><td>Asset ID</td><td>Event</td><td><code>asset_id</code></td></tr><tr><td>Asset Name</td><td>Event</td><td><code>asset_name</code></td></tr><tr><td>Collection ID</td><td>Event</td><td><code>collection_id</code></td></tr><tr><td>Collection Name</td><td>Event</td><td><code>collection_name</code></td></tr><tr><td>File Object ID</td><td>Event</td><td><code>file_object_id</code></td></tr><tr><td>File Type</td><td>Event</td><td><code>file_type</code></td></tr></tbody></table><h2 id="set-measurement-id-in-elevator" tabindex="-1">Set Measurement ID in Elevator <a class="header-anchor" href="#set-measurement-id-in-elevator" aria-label="Permalink to &quot;Set Measurement ID in Elevator&quot;">​</a></h2><p>In <strong>Google Analytics</strong>, go to Web Stream details. (This may pop-up automatically after creating a new property.)</p><ol><li><p>Go to <code>Admin &gt; Data Streams</code><img src="'+r+'" alt="Getting your Data Stream"></p></li><li><p>Choose your the data stream for your elevator instance. <img src="'+c+'" alt="Select Data Stream"></p></li><li><p>Copy your <strong>Measurement ID</strong>, something like <code>G-123456</code>. <img src="'+d+'" alt="Getting Measurement ID"></p></li></ol><p>Then, <strong>in your elevator instance</strong>:</p><ol><li><p>Login to elevator. (You will need to be an admin.)</p></li><li><p>Choose <code>Admin &gt; Instance Settings</code></p></li><li><p>In the <code>Google Analytics Key</code> field, paste your Measurement ID <img src="'+p+'" alt="Enter your google analytics key"></p></li><li><p>Save</p></li></ol><h2 id="verify-data-is-flowing" tabindex="-1">Verify data is flowing <a class="header-anchor" href="#verify-data-is-flowing" aria-label="Permalink to &quot;Verify data is flowing&quot;">​</a></h2><p>Back in <strong>Google Analytics</strong>, you can verify that data is flowing from Elevator to analytics using <a href="https://tagassistant.google.com" target="_blank" rel="noreferrer">Google Tag Assistant</a>. Tag assistant will open a debug view to show which events are sent.</p><ol><li>Go to <a href="https://tagassistant.google.com" target="_blank" rel="noreferrer">tagassistant.google.com</a></li><li>Choose <code>Add Domain</code>, and enter your elevator website URL, e.g. <code>https://dcl.elevator.umn.edu</code>.</li><li>Click <code>Connect</code> and tag assistant will open your elevator website in a new window or tab. This window/tab is in &quot;Debug Mode&quot;, meaning any events from this browser window will show up in the Tag Assistant window.</li><li>Click around, or enter a search term in the Elevator window. In the tag assistant you should see the events.</li></ol><blockquote><p><strong>NOTE:</strong> Some browsers (e.g. Brave) will block transmitting analytics data by default. If you&#39;re testing your elevator site, be sure to disable this feature temporarily.</p></blockquote><video controls width="640"><source src="'+u+'"></video><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><ul><li>Under <code>Reporting</code>, you should see activity in the <code>Realtime overview</code> and <code>Realtime pages</code> reports shortly after Google Analytics is set up.</li><li>It will take 24 hours before you&#39;ll have enough data to create custom analytics reports.</li></ul><p><img src="'+g+'" alt="Analytics report"></p><p>Above is an example of a report using elevator data for asset and collections. To set up a report like this yourself, go to <code>Explore &gt; Blank</code>, and then set:</p><p><strong>VARIABLES:</strong></p><ul><li>Date: Last 28 days</li><li>Segments: <code>All Users</code></li><li>Dimensions: <ul><li>Under <code>Event</code>: <code>Event Name</code></li><li>Under <code>Custom</code>: <code>Collection Name</code>, <code>Asset Name</code></li></ul></li><li>Metrics: <code>Event &gt; Event Count</code></li></ul><p><strong>SETTINGS</strong></p><ul><li>Segment Comparisons: <code>All Users</code></li><li>Pivot: First Column</li><li>Rows: <ul><li><code>Event Name</code></li><li><code>Collection Name</code></li><li><code>Asset Name</code></li></ul></li><li>Values: <code>Event Count</code></li></ul><p>You can use <code>Filter</code> to limit results to specific events.</p>',31)])])}const C=t(m,[["render",h]]);export{A as __pageData,C as default};
